from src.services.billing import charge_invoice

class FakeGateway:
    def __init__(self): self.calls = []
    def charge(self, invoice_id, amount): self.calls.append((invoice_id, amount)); return {'ok': True}

g = FakeGateway()
assert charge_invoice({'id': 'INV-1', 'status': 'paid', 'amount_due': 100}, g) == {'invoice_id': 'INV-1', 'charged': False, 'reason': 'already_paid'}
assert g.calls == []
assert charge_invoice({'id': 'INV-2', 'status': 'open', 'amount_due': 250}, g) == {'invoice_id': 'INV-2', 'charged': True, 'result': {'ok': True}}
assert g.calls == [('INV-2', 250)]
print('ok')
